use bevy::prelude::{Commands, MessageReader, ResMut};

use crate::effects;

/// 611.2a A continuous effect generated by the resolution of a spell or ability lasts as long as
/// stated by the spell or ability creating it (such as “until end of turn”). If no duration is
/// stated, it lasts until the end of the game.
///
/// # See also
///
/// 611.2c If a continuous effect generated by the resolution of a spell or ability modifies the
/// characteristics or changes the controller of any objects, the set of objects it affects is
/// determined when that continuous effect begins. After that point, the set won’t change. (Note
/// that this works differently than a continuous effect from a static ability.) A continuous effect
/// generated by the resolution of a spell or ability that doesn’t modify the characteristics or
/// change the controller of any objects modifies the rules of the game, so it can affect objects
/// that weren’t affected when that continuous effect began. If a single continuous effect has parts
/// that modify the characteristics or changes the controller of any objects and other parts that
/// don’t, the set of objects each part applies to is determined independently.
///
/// 613.4c Layer 7c: Effects and counters that modify power and/or toughness (but don’t set power
/// and/or toughness to a specific number or value) are applied.
pub fn r611_2a_continuous_effects(
    mut modifications: MessageReader<effects::PowerToughnessModified>,
    mut grants: MessageReader<effects::KeywordGranted>,
    mut commands: Commands,
    mut timestamp: ResMut<effects::Timestamp>,
) {
    for modification in modifications.read() {
        commands.spawn(effects::ContinuousEffect {
            affected: modification.target,
            source: None,
            modification: effects::Modification::Characteristic(effects::Layered::ModifyPT {
                power: modification.power,
                toughness: modification.toughness,
            }),
            until: effects::Duration::UntilEndOfTurn,
            timestamp: timestamp.advance(),
        });
    }
    for grant in grants.read() {
        commands.spawn(effects::ContinuousEffect {
            affected: grant.target,
            source: None,
            modification: effects::Modification::Characteristic(effects::Layered::GainKeyword(
                grant.keyword.clone(),
            )),
            until: effects::Duration::UntilEndOfTurn,
            timestamp: timestamp.advance(),
        });
    }
}

#[cfg(test)]
mod tests {
    use crate::damage;
    use crate::effects;
    use crate::mana;
    use crate::testing::*;
    use crate::{BATTLEFIELD, GRAVEYARD, HAND};

    #[test]
    fn giant_growth_applies_power_toughness_modifier() -> TestResult {
        let (mut game, [p1, p2]) = MockGame::new([
            P1.hand([GIANT_GROWTH]).battlefield([GRIZZLY_BEARS]).mana_pool(mana![G]),
            P2,
        ]);
        let [growth] = game.player(p1).cards_in(HAND).exactly::<1>(GIANT_GROWTH)?;
        let [bears] = game.player(p1).cards_in(BATTLEFIELD).exactly::<1>(GRIZZLY_BEARS)?;
        game.play([
            p1.cast(growth).targeting(bears).pass_priority(),
            p2.pass_priority(),
        ])?;
        assert_eq!(game.pt(bears), Some(crate::pt!(5, 5)));
        assert!(game.player(p1).cards_in(GRAVEYARD).has(growth));
        Ok(())
    }

    #[test]
    fn giant_growth_saves_a_creature_from_lethal_damage() -> TestResult {
        let (mut game, [p1, p2]) = MockGame::new([
            P1.hand([LIGHTNING_BOLT]).mana_pool(mana![R]),
            P2.hand([GIANT_GROWTH]).battlefield([GRIZZLY_BEARS]).mana_pool(mana![G]),
        ]);
        let [bolt] = game.player(p1).cards_in(HAND).exactly::<1>(LIGHTNING_BOLT)?;
        let [growth] = game.player(p2).cards_in(HAND).exactly::<1>(GIANT_GROWTH)?;
        let [bears] = game.player(p2).cards_in(BATTLEFIELD).exactly::<1>(GRIZZLY_BEARS)?;

        game.play([
            p1.cast(bolt).targeting(bears).pass_priority(),
            p2.cast(growth).targeting(bears).pass_priority(),
            p1.pass_priority(),
            p1.pass_priority(),
            p2.pass_priority(),
        ])?;

        assert!(game.player(p2).cards_in(BATTLEFIELD).has(bears));
        let damage = game.get::<damage::Damage>(bears);
        assert_eq!(damage, Some(damage::Damage(3)));
        assert_eq!(game.pt(bears), Some(crate::pt!(5, 5)));
        Ok(())
    }

    #[test]
    fn two_giant_growths_give_plus_six_plus_six() -> TestResult {
        let (mut game, [p1, p2]) = MockGame::new([
            P1.hand([GIANT_GROWTH, GIANT_GROWTH])
                .battlefield([GRIZZLY_BEARS])
                .mana_pool(mana![G, G]),
            P2,
        ]);
        let [growth_1, growth_2] = game.player(p1).cards_in(HAND).exactly::<2>(GIANT_GROWTH)?;
        let [bears] = game.player(p1).cards_in(BATTLEFIELD).exactly::<1>(GRIZZLY_BEARS)?;
        game.play([
            p1.cast(growth_1).targeting(bears),
            p1.cast(growth_2).targeting(bears).pass_priority(),
            p2.pass_priority(),
            p1.pass_priority(),
            p2.pass_priority(),
        ])?;
        let timestamps = game.with_query::<&effects::ContinuousEffect, Vec<u64>>(|effects| {
            effects.iter().map(|effect| effect.timestamp).collect()
        });
        assert_eq!(timestamps.len(), 2);
        assert_ne!(timestamps[0], timestamps[1]);
        assert_eq!(game.pt(bears), Some(crate::pt!(8, 8)));
        Ok(())
    }
}
